class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def arr_to_list(arr):
    head = None
    tail = None
    for v in arr:
        node = ListNode(v)
        if not head:
            head, tail = node, node
        else:
            tail.next = node
            tail = node
    return head


def list_to_arr(head):
    result = []
    node = head
    while node:
        result.append(node.val)
        node = node.next
    return result


def insertion_sort_list(head_arr):
    head = arr_to_list(head_arr)
    dummy = ListNode(0)
    curr = head

    while curr:
        nxt = curr.next
        prev = dummy
        while prev.next and prev.next.val < curr.val:
            prev = prev.next
        curr.next = prev.next
        prev.next = curr
        curr = nxt

    return list_to_arr(dummy.next)

